from __future__ import annotations

"""Standalone dark Mobile V1 RC shell matching the approved consolidated mock.

This renderer intentionally does not inherit the legacy Yipman HTML shell. It
uses the live FULL MYSQL APIs for urgent review, Quick search, Ordering and
Price Review while keeping the official /app/yipman-v1/ route unchanged.
"""


def yipman_mobile_v1_exact_html(version: str = "") -> str:
    v = str(version or "")
    return r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover">
<meta name="theme-color" content="#0b1117">
<title>YipMan Mobile V1 RC</title>
<style>
*{box-sizing:border-box}html,body{margin:0;height:100%;background:#0b1117;color:#f1f5f8;font-family:Arial,sans-serif;overflow:hidden}button,input{font:inherit}button{color:inherit}
:root{--bg:#0b1117;--panel:#141d26;--panel2:#17212b;--line:#2a3744;--muted:#8493a1;--blue:#4fa1ff;--danger:#ff737f;--warn:#e6b85c;--good:#79c890;--soft:#a9b6c2}
.app{height:100%;position:relative}.page{display:none;height:100%;overflow:auto;padding:12px 12px 190px;overscroll-behavior:contain}.page.active{display:block}.top{position:sticky;top:0;z-index:20;background:rgba(11,17,23,.96);backdrop-filter:blur(12px);padding:5px 0 8px}.title{font-size:27px;font-weight:1000;letter-spacing:-.02em}.sub{margin-top:3px;color:var(--muted);font-size:11px;font-weight:850}.row{display:flex;align-items:center;gap:10px}.space{justify-content:space-between}.iconbtn{width:42px;height:42px;border:1px solid var(--line);border-radius:12px;background:#111922;font-size:24px;font-weight:1000}
.card,.action-card{background:linear-gradient(180deg,#17212b,#131c25);border:1px solid var(--line);border-radius:18px;box-shadow:0 8px 22px rgba(0,0,0,.18);margin-bottom:12px;overflow:hidden}.card-head{padding:13px 14px 8px}.card-body{padding:12px 14px 14px}.card-title{font-size:20px;font-weight:1000}.card-sub{margin-top:4px;font-size:11px;color:var(--muted);font-weight:800}.pill{display:inline-flex;align-items:center;min-height:26px;padding:5px 9px;border-radius:999px;border:1px solid #3a4654;background:#11181f;color:#b8c4d0;font-size:9px;font-weight:1000}.pill.danger{border-color:#6d3540;background:#2b181d;color:#ffabb2}.pill.warn{border-color:#67542c;background:#2c2415;color:#f0ce7f}.pill.blue{border-color:#315f91;background:#172c42;color:#bfdcff}.pill.good{border-color:#386747;background:#18271d;color:#a7d8b3}
.urgent-summary{display:grid;grid-template-columns:1.15fr repeat(4,1fr);border:1px solid var(--line);border-radius:13px;overflow:hidden;background:#101820}.urgent-summary button{height:38px;border:0;border-right:1px solid var(--line);background:transparent;display:flex;align-items:center;justify-content:center;gap:4px;padding:0 3px}.urgent-summary button:last-child{border-right:0}.urgent-summary button.active{background:#20384d}.urgent-summary strong{font-size:13px}.urgent-summary span{font-size:8px;color:#9daab6;font-weight:900}.updated{font-size:8px;color:#657584;font-weight:900;margin:5px 2px 8px}.urgent-list{display:grid;gap:10px}.urgent-card{border:1px solid #31404d;border-left:5px solid #667d92;border-radius:18px;background:linear-gradient(180deg,#17212b,#141d26);padding:13px}.urgent-card.price{border-left-color:#be6faf}.urgent-card.order{border-left-color:#d4aa54}.urgent-card.fresh{border-left-color:#59a8be}.urgent-top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.urgent-name{font-size:21px;font-weight:1000;line-height:1.08}.urgent-meta{font-size:10px;color:#8493a1;font-weight:850;margin-top:4px}.urgent-action{font-size:22px;font-weight:1000;margin-top:9px}.urgent-why{font-size:11px;color:#abb7c2;line-height:1.35;font-weight:760;margin-top:6px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:10px}.metric{border:1px solid #2b3945;background:#101820;border-radius:11px;padding:8px;text-align:center;min-width:0}.metric b{display:block;font-size:7px;color:#7e8c99}.metric span{display:block;margin-top:4px;font-size:12px;font-weight:1000;overflow-wrap:anywhere}.ignore{width:100%;min-height:46px;margin-top:10px;border:1px solid #68562f;border-radius:12px;background:#2a2418;color:#f0d184;font-weight:1000}
.bottom{position:fixed;left:0;right:0;bottom:0;z-index:80;background:linear-gradient(180deg,rgba(11,17,23,0),#0b1117 16%);padding:8px 12px calc(10px + env(safe-area-inset-bottom))}.searchdock{display:none;margin:0 auto 7px;max-width:680px;background:#fff;border:3px solid #1769e0;border-radius:18px;min-height:62px;grid-template-columns:45px minmax(0,1fr) 62px;align-items:center;padding:4px 7px}.quick-on .searchdock{display:grid}.searchdock span{width:36px;height:36px;border-radius:11px;background:#e8f3ff;color:#0d5f9f;display:grid;place-items:center;font-size:21px;font-weight:1000}.searchdock input{width:100%;min-width:0;border:0;outline:0;background:transparent;color:#16202a;font-size:19px;font-weight:850;padding:10px 6px}.searchdock button{height:40px;border:0;border-radius:10px;background:#eaf1f6;color:#31516a;font-size:10px;font-weight:1000}.nav{max-width:680px;margin:auto;height:76px;border:1px solid #314252;border-radius:24px;background:#1b2a38;display:grid;grid-template-columns:repeat(4,1fr);overflow:hidden;box-shadow:0 10px 30px rgba(0,0,0,.35)}.nav button{border:0;background:transparent;color:#8d9baa;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;font-size:10px;font-weight:1000}.nav button i{font-style:normal;font-size:25px;line-height:1}.nav button.active{background:#f6f7f9;color:#0672c7}.nav button.active i{background:#e0f1ff;border-radius:999px;padding:4px 14px}
.big-entry{width:100%;min-height:90px;margin-bottom:10px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(180deg,#17212b,#141d26);text-align:left;padding:14px}.big-entry b{display:block;font-size:21px}.big-entry span{display:block;color:#93a1ae;font-size:11px;margin-top:6px;line-height:1.35}.field{margin-bottom:10px}.field label{display:block;font-size:8px;color:#81909d;font-weight:1000;margin-bottom:5px}.input,.search{width:100%;min-height:48px;border:1px solid #33414e;border-radius:12px;background:#0f171f;color:#eef4f8;padding:9px 11px;font-size:14px;font-weight:850}.form2{display:grid;grid-template-columns:1fr 1fr;gap:8px}.order-main{font-size:23px;font-weight:1000}.why{margin-top:6px;color:#a8b4bf;font-size:11px;line-height:1.35}.summary3{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:10px}.stat{background:#101820;border:1px solid #2b3945;border-radius:11px;padding:8px;text-align:center;min-width:0}.stat b{display:block;color:#7f8e9b;font-size:7px}.stat span{display:block;font-size:12px;font-weight:1000;margin-top:4px;overflow-wrap:anywhere}.loading,.empty{border:1px dashed #344452;border-radius:16px;background:#111820;color:#81919f;padding:22px 14px;text-align:center;font-size:11px;font-weight:850}
.price-head{padding-bottom:8px}.price-head-row{display:flex;justify-content:space-between;align-items:center;gap:10px}.searchbtn{width:48px;height:42px;border:1px solid #344352;border-radius:12px;background:#111a22;font-size:22px}.price-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:8px}.price-summary div{height:44px;border:1px solid #30404e;border-radius:12px;background:#101820;display:flex;align-items:center;justify-content:center;gap:5px}.price-summary b{font-size:17px}.price-summary span{font-size:8px;color:#8c9aa7;font-weight:1000}.filter2{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;margin-top:8px}.filter4{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:7px}.filterbtn{min-height:40px;border:1px solid #364554;border-radius:999px;background:#111922;color:#b4bfca;font-size:10px;font-weight:1000}.filterbtn.active{background:#245a87;border-color:#4c91cf;color:#fff}.filter4 .filterbtn{background:#21192a;border-color:#594169}.filter4 .filterbtn.active{background:#4a2f5a}.prefixrow .filterbtn{background:#17261a;border-color:#395e3d}.prefixrow .filterbtn.active{background:#3f6a43}.price-queue{margin-top:10px}.family-card{border:1px solid #2e3a47;border-radius:19px;background:#18212b;margin-bottom:12px;overflow:hidden}.family-head{display:grid;grid-template-columns:6px minmax(0,1fr) 75px}.family-accent{background:#5ea2ff}.family-card.urgent .family-accent{background:#ff747f}.family-main{padding:15px}.family-title{font-size:21px;font-weight:1000}.family-sub{font-size:11px;color:#8998a5;margin-top:5px;font-weight:850}.family-side{padding:14px 12px;text-align:right;display:flex;flex-direction:column;justify-content:center}.family-side b{font-size:25px}.family-side span{font-size:8px;color:#7d8c99;font-weight:900}.direct-card{border:1px solid #31404d;border-radius:18px;background:#17212b;margin-bottom:12px;padding:14px}.result-name{font-size:20px;font-weight:1000}.action-meta{font-size:10px;color:#8796a3;font-weight:800;margin-top:4px}.actionbox{margin-top:10px;border:1px solid #334352;border-radius:13px;background:#101820;padding:11px}.actionbox.danger{border-color:#6b3540;background:#28181d}.action-label{font-size:8px;color:#8695a2;font-weight:1000}.action-value{font-size:22px;font-weight:1000;margin-top:4px}.search-results{display:none}.search-results.show{display:block}.quick-result{border:1px solid #314252;border-radius:17px;background:#16212b;padding:14px;margin-bottom:10px}.quick-result h3{font-size:20px;margin:0}.quick-result p{font-size:10px;color:#93a2af;margin:5px 0 0}.morebtn{width:100%;min-height:72px;margin-bottom:10px;border:1px solid var(--line);border-radius:17px;background:#17212b;padding:13px;text-align:left}.morebtn b{font-size:18px}.morebtn span{display:block;margin-top:4px;font-size:10px;color:#8f9eaa}.morebtn.primary{background:linear-gradient(135deg,#174b77,#1c6aa8);border:0}
@media(max-width:390px){.title{font-size:24px}.urgent-name{font-size:19px}.urgent-action{font-size:20px}.nav{height:72px}.page{padding-left:10px;padding-right:10px}}
</style>
</head>
<body>
<div class="app quick-on" id="app">
<section class="page active" id="quick">
  <div class="top"><div class="urgent-summary" id="urgentSummary"><button class="active" data-uf="all"><strong>0</strong><span>Urgent</span></button><button data-uf="price"><strong>0</strong><span>Price</span></button><button data-uf="order"><strong>0</strong><span>Order</span></button><button data-uf="fresh"><strong>0</strong><span>Fresh</span></button><button data-uf="inventory"><strong>0</strong><span>Inventory</span></button></div><div class="updated" id="updated">Updating…</div></div>
  <div id="urgentList" class="urgent-list"><div class="loading">Loading urgent actions…</div></div>
  <div id="quickResults" class="search-results"></div>
</section>
<section class="page" id="ordering">
  <div class="top"><div class="title">Ordering</div><div class="sub">Calendar-first · Regular + Promotion</div></div>
  <button class="big-entry" data-open="regular"><b>Regular Ordering</b><span>Select delivery date → all observed Families → suggested order decisions</span></button>
  <button class="big-entry" data-open="promo"><b>Promotion Ordering</b><span>Promo details → add UPCs → Calculate All → one-time suggestions</span></button>
</section>
<section class="page" id="regular">
  <div class="top"><div class="row"><button class="iconbtn" data-open="ordering">‹</button><div><div class="title">Regular Ordering</div><div class="sub">Calendar-first</div></div></div></div>
  <div class="card"><div class="card-body"><div class="form2"><div class="field"><label>DELIVERY DATE</label><input id="deliveryDate" class="input" type="date"></div><div class="field"><label>NEXT DELIVERY DATE</label><input id="nextDeliveryDate" class="input" type="date"></div></div></div></div>
  <div id="regularResults"><div class="loading">Loading ordering calendar…</div></div>
</section>
<section class="page" id="promo">
  <div class="top"><div class="row"><button class="iconbtn" data-open="ordering">‹</button><div><div class="title">Promotion Ordering</div><div class="sub">Session-only suggestions</div></div></div></div>
  <div class="card"><div class="card-head"><div class="card-title">Promotion Setup</div></div><div class="card-body"><div class="form2"><div class="field"><label>PROMO START</label><input class="input" type="date"></div><div class="field"><label>PROMO END</label><input class="input" type="date"></div><div class="field"><label>PROMO PRICE</label><input class="input" inputmode="decimal" placeholder="$0.00"></div><div class="field"><label>DELIVERY DATE</label><input class="input" type="date"></div></div></div></div>
  <div class="card"><div class="card-head"><div class="card-title">Add Promotion Items</div><div class="card-sub">Search + Add · Paste list/form</div></div><div class="card-body"><input class="search" placeholder="Search UPC / Article / name"><button class="ignore" style="margin-top:8px">Paste Promo List / Form</button><button class="ignore" style="border-color:#35689a;background:#17304a;color:#cfe3ff">Calculate All</button></div></div>
</section>
<section class="page" id="price">
  <div class="top price-head"><div class="price-head-row"><div><div class="title">Price Review</div><div class="sub">Unified Action Queue</div></div><button class="searchbtn" id="priceSearchBtn">⌕</button></div>
  <div class="price-summary"><div><b id="priceActions">0</b><span>Actions</span></div><div><b id="priceUrgent">0</b><span>Urgent</span></div><div><b id="priceFamilies">0</b><span>Families</span></div></div>
  <div class="filter2"><button class="filterbtn active" data-pf="all">All</button><button class="filterbtn" data-pf="urgent">Urgent</button></div>
  <div class="filter4"><button class="filterbtn" data-pf="reg">REG</button><button class="filterbtn" data-pf="tpr">TPR</button><button class="filterbtn" data-pf="clearance">Clearance</button><button class="filterbtn" data-pf="sale">SALE</button></div>
  <div class="filter2 prefixrow"><button class="filterbtn" data-pf="240249">240/249</button><button class="filterbtn" data-pf="245">245</button></div></div>
  <div id="priceSearchWrap" style="display:none;margin-bottom:10px"><input id="priceSearch" class="search" placeholder="Search Family / UPC / Article / Name"></div>
  <div class="price-queue" id="priceQueue"><div class="loading">Loading price actions…</div></div>
</section>
<section class="page" id="more">
  <div class="top"><div class="title">More</div><div class="sub">Back Office + lightweight options</div></div>
  <button class="morebtn primary" onclick="location.href='/app/backoffice'"><b>Back Office</b><span>Data Center · Batch / Processing · QA / Fixes · Inventory / PI</span></button>
  <button class="morebtn"><b>Settings</b><span>Mobile display and established store rules</span></button>
  <button class="morebtn"><b>App Info / About</b><span>YipMan Mobile V1 · Exact Mock RC · FULL MYSQL __VERSION__</span></button>
</section>
<div class="bottom"><form class="searchdock" id="quickForm"><span>⌕</span><input id="quickSearch" placeholder="Search item, UPC, article..." autocomplete="off" enterkeyhint="search"><button id="quickClear" type="button">CLEAR</button></form><div class="nav"><button class="active" data-nav="quick"><i>⌕</i>QUICK</button><button data-nav="ordering"><i>▤</i>ORDER</button><button data-nav="price"><i>$</i>PRICE</button><button data-nav="more"><i>•••</i>MORE</button></div></div>
</div>
<script>
(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>{const x=Number(v);return Number.isFinite(x)?x:null};const fmt=(v,d=1)=>{const x=num(v);return x===null?'—':x.toLocaleString(undefined,{maximumFractionDigits:d})};const money=v=>{const x=num(v);return x===null?'—':'$'+x.toFixed(2)};const prefix=v=>String(v||'').replace(/^0+/,'').slice(0,3);
const api=async(url,opt={})=>{const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...opt});if(!r.ok)throw new Error((await r.text().catch(()=>''))||('HTTP '+r.status));return r.json()};
let urgent=[],priceRows=[],orderRows=[],uf='all',pf='all';
function show(id){$$('.page').forEach(p=>p.classList.toggle('active',p.id===id));$$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===id));$('#app').classList.toggle('quick-on',id==='quick');if(id==='regular')loadOrdering();if(id==='price')loadPrice();}
$$('[data-nav]').forEach(b=>b.onclick=()=>show(b.dataset.nav));$$('[data-open]').forEach(b=>b.onclick=()=>show(b.dataset.open));
function ignoreKey(k){return 'yipman-exact-ignore:'+k}function isIgnored(k){const t=Number(localStorage.getItem(ignoreKey(k))||0);if(t>Date.now())return true;if(t)localStorage.removeItem(ignoreKey(k));return false}function setIgnore(k){localStorage.setItem(ignoreKey(k),String(Date.now()+12*60*60*1000));loadUrgent();if($('#price').classList.contains('active'))renderPrice()}
function nameOf(r){return String(r?.family_name||r?.name||r?.description||r?.family_article_name||r?.family_article||'Item')};function famOf(r){return String(r?.family_article_number||r?.family_article||r?.family_id||'')};function upcOf(r){return String(r?.upc||r?.selling_upc||r?.upc_number||'')};function artOf(r){return String(r?.receiving_article||r?.receiving_article_number||r?.article_number||r?.family_article_number||r?.family_article||'')}
function priceReason(r){return String(r?.why||r?.reason||r?.suggestion_reason||r?.recommendation_reason||'Review current pricing evidence.')};function suggestedPrice(r){return r?.final_tpr_price_suggestion??r?.tpr_suggestion_price??r?.testing_price??r?.suggested_price??r?.candidate_price??r?.suggested_reg_price??null}function currentPrice(r){return r?.current_price??r?.effective_price??null}
function trueUrgentPrice(r){const s=(priceReason(r)+' '+String(r?.recommendation_type||'')+' '+String(r?.action_type||'')+' '+String(r?.reason_code||'')).toUpperCase();return !!r?.priority_240_249_mismatch||/FRESH|SPOIL|EXPIR|CLEARANCE|DOH|SELL.?THROUGH|SALE.*WARN|PRICE.*INTEGRITY/.test(s)}
function priceType(r){const s=(String(r?.recommendation_type||'')+' '+String(r?.action_type||'')+' '+String(r?.price_type||'')+' '+priceReason(r)).toUpperCase();if(s.includes('CLEAR'))return'clearance';if(s.includes('SALE'))return'sale';if(s.includes('TPR'))return'tpr';return'reg'}
function buildUrgentPrice(rows){const out=[];for(const r of rows||[]){const upc=upcOf(r);if(!upc||prefix(upc)==='249'||!trueUrgentPrice(r))continue;const fresh=/FRESH|SPOIL|EXPIR|CLEAR|DOH|SELL.?THROUGH/i.test(priceReason(r)+' '+String(r?.recommendation_type||''));const sp=suggestedPrice(r),cp=currentPrice(r),oh=r?.current_oh??r?.effective_oh??r?.oh,uom=r?.current_oh_uom||r?.effective_oh_uom||r?.oh_uom||'';out.push({key:'p:'+upc,type:fresh?'fresh':'price',name:nameOf(r),family:famOf(r),upc,article:artOf(r),pill:fresh?'FRESH / PRICE':'PRICE',action:(fresh?'TPR-FRESH ':'PRICE ACTION ')+(sp!==null?money(sp):'REVIEW'),why:priceReason(r),metrics:[['EFF OH',oh==null?'—':fmt(oh)+' '+uom],['CURRENT',money(cp)],['SUGGEST',money(sp)]],score:fresh?100:95})}return out}
function buildUrgentOrder(rows){const out=[];for(const r of rows||[]){const q=num(r?.suggested_delivery_qty);if(!(q>0))continue;const family=famOf(r),uom=r?.suggested_delivery_uom||r?.order_uom||r?.effective_oh_uom||'',eff=r?.effective_oh??r?.oh;out.push({key:'o:'+(family||artOf(r)||nameOf(r)),type:'order',name:nameOf(r),family,upc:upcOf(r),article:artOf(r),pill:'ORDER',action:'ORDER '+fmt(q,1)+' '+uom,why:String(r?.roster_reason||r?.reason||r?.suggestion_reason||'Projected stock is below coverage demand.'),metrics:[['EFF OH',eff==null?'—':fmt(eff)+' '+(r?.effective_oh_uom||'')],['DELIVERY',r?.delivery_date||r?.selected_delivery_date||'—'],['NEXT',r?.next_delivery_date||'—']],score:r?.projected_stockout?98:88})}return out}
async function getOrdering(){const cal=await api('/v1/yipman/ordering-calendar?lookback_days=180').catch(()=>null);const d=String(cal?.default_delivery_date||''),n=String(cal?.default_next_delivery_date||'');if(d){$('#deliveryDate').value=d;$('#nextDeliveryDate').value=n||'';const data=await api('/v1/yipman/ordering-review?category=ALL&delivery_date='+encodeURIComponent(d)+(n?'&next_delivery_date='+encodeURIComponent(n):'')).catch(()=>null);return data?.rows||[]}return[]}
async function loadUrgent(){try{const [p,o]=await Promise.all([api('/v1/yipman/pricing-review?category=ALL&limit=1000').catch(()=>({rows:[]})),getOrdering()]);priceRows=p.rows||[];orderRows=o||[];urgent=[...buildUrgentPrice(priceRows),...buildUrgentOrder(orderRows)].filter(x=>!isIgnored(x.key)).sort((a,b)=>b.score-a.score);renderUrgent();$('#updated').textContent='Updated '+new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}catch(e){$('#urgentList').innerHTML='<div class="empty">Urgent feed unavailable · '+esc(e.message)+'</div>'}}
function renderUrgent(){const counts={all:urgent.length,price:0,order:0,fresh:0,inventory:0};urgent.forEach(x=>counts[x.type]=(counts[x.type]||0)+1);$$('[data-uf]').forEach(b=>{b.querySelector('strong').textContent=counts[b.dataset.uf]||0;b.classList.toggle('active',b.dataset.uf===uf)});const rows=uf==='all'?urgent:urgent.filter(x=>x.type===uf);$('#urgentList').innerHTML=rows.length?rows.map(x=>`<article class="urgent-card ${esc(x.type)}"><div class="urgent-top"><div><div class="urgent-name">${esc(x.name)}</div><div class="urgent-meta">${x.family?'Family '+esc(x.family):''}${x.upc?' · UPC '+esc(x.upc):''}${x.article?' · Article '+esc(x.article):''}</div></div><span class="pill ${x.type==='fresh'?'danger':x.type==='order'?'warn':'blue'}">${esc(x.pill)}</span></div><div class="urgent-action">${esc(x.action)}</div><div class="urgent-why">${esc(x.why)}</div><div class="metrics">${x.metrics.map(m=>`<div class="metric"><b>${esc(m[0])}</b><span>${esc(m[1])}</span></div>`).join('')}</div><button class="ignore" data-ignore="${esc(x.key)}">Ignore 12h</button></article>`).join(''):'<div class="empty">No urgent actions in this filter.</div>';$$('[data-ignore]',$('#urgentList')).forEach(b=>b.onclick=()=>setIgnore(b.dataset.ignore))}
$$('[data-uf]').forEach(b=>b.onclick=()=>{uf=b.dataset.uf;renderUrgent()});
let qt;$('#quickSearch').addEventListener('input',()=>{clearTimeout(qt);const q=$('#quickSearch').value.trim();$('#quickClear').style.visibility=q?'visible':'hidden';if(!q){$('#quickResults').classList.remove('show');$('#urgentList').style.display='grid';return}qt=setTimeout(()=>searchQuick(q),260)});$('#quickForm').onsubmit=e=>{e.preventDefault();const q=$('#quickSearch').value.trim();if(q)searchQuick(q);$('#quickSearch').blur()};$('#quickClear').onclick=()=>{$('#quickSearch').value='';$('#quickSearch').blur();$('#quickResults').classList.remove('show');$('#urgentList').style.display='grid'};
async function searchQuick(q){try{const d=await api('/v1/backoffice/inventory?category=ALL&limit=80&lightweight=true&include_oh=true&q='+encodeURIComponent(q));const rows=d.rows||[];$('#urgentList').style.display='none';const box=$('#quickResults');box.classList.add('show');box.innerHTML=rows.length?rows.slice(0,30).map((r,i)=>`<div class="quick-result"><h3>${esc(nameOf(r))}</h3><p>${famOf(r)?'Family '+esc(famOf(r)):''}${upcOf(r)?' · UPC '+esc(upcOf(r)):''}${artOf(r)?' · Article '+esc(artOf(r)):''}</p><div class="summary3"><div class="stat"><b>EFFECTIVE OH</b><span>${fmt(r?.effective_oh??r?.current_oh??r?.oh)} ${esc(r?.effective_oh_uom||r?.oh_uom||'')}</span></div><div class="stat"><b>7D MVT</b><span>${fmt(r?.family_group_movement_7d??r?.movement_7d)}</span></div><div class="stat"><b>CURRENT PRICE</b><span>${money(r?.current_price)}</span></div></div></div>`).join(''):'<div class="empty">No matches</div>'}catch(e){$('#quickResults').classList.add('show');$('#quickResults').innerHTML='<div class="empty">Search unavailable · '+esc(e.message)+'</div>'}}
async function loadOrdering(){const d=$('#deliveryDate').value,n=$('#nextDeliveryDate').value;if(!d){await getOrdering();return loadOrdering()}$('#regularResults').innerHTML='<div class="loading">Loading order suggestions…</div>';try{const data=await api('/v1/yipman/ordering-review?category=ALL&delivery_date='+encodeURIComponent(d)+(n?'&next_delivery_date='+encodeURIComponent(n):''));orderRows=data.rows||[];renderOrdering()}catch(e){$('#regularResults').innerHTML='<div class="empty">Ordering unavailable · '+esc(e.message)+'</div>'}}
function renderOrdering(){const rows=[...orderRows].sort((a,b)=>(num(b?.suggested_delivery_qty)||0)-(num(a?.suggested_delivery_qty)||0));$('#regularResults').innerHTML=rows.length?rows.map((r,i)=>{const q=num(r?.suggested_delivery_qty)||0,eff=r?.effective_oh??r?.oh,uom=r?.suggested_delivery_uom||r?.order_uom||'';const key='reg:'+famOf(r)+':'+($('#deliveryDate').value||'');if(isIgnored(key))return'';return`<div class="card"><div class="card-head"><div class="row space"><div><div class="card-title">${esc(nameOf(r))}</div><div class="card-sub">Family ${esc(famOf(r)||'—')} · Receiving ${esc(artOf(r)||'—')}</div></div><span class="pill ${q>0?'danger':''}">${q>0?'ORDER':'NO ORDER'}</span></div></div><div class="card-body"><div class="order-main">${q>0?'ORDER '+fmt(q,1)+' '+esc(uom):'NO ORDER'}</div><div class="why"><b>Why:</b> ${esc(r?.roster_reason||r?.reason||r?.suggestion_reason||'Coverage calculation complete.')}</div><div class="summary3"><div class="stat"><b>EFFECTIVE OH</b><span>${fmt(eff)} ${esc(r?.effective_oh_uom||'')}</span></div><div class="stat"><b>DELIVERY</b><span>${esc(r?.delivery_date||$('#deliveryDate').value)}</span></div><div class="stat"><b>NEXT</b><span>${esc(r?.next_delivery_date||$('#nextDeliveryDate').value||'—')}</span></div></div>${q>0?`<button class="ignore" data-oi="${esc(key)}">Ignore 12h</button>`:''}</div></div>`}).join(''):'<div class="empty">No observed families for this delivery window.</div>';$$('[data-oi]').forEach(b=>b.onclick=()=>{setIgnore(b.dataset.oi);renderOrdering()})}
$('#deliveryDate').onchange=loadOrdering;$('#nextDeliveryDate').onchange=loadOrdering;
async function loadPrice(){if(!priceRows.length){try{const d=await api('/v1/yipman/pricing-review?category=ALL&limit=1000');priceRows=d.rows||[]}catch(e){$('#priceQueue').innerHTML='<div class="empty">Price Review unavailable · '+esc(e.message)+'</div>';return}}renderPrice()}
function actionablePrice(r){return !!r?.actionable||!!r?.tpr_suggestion_actionable||!!r?.priority_240_249_mismatch||String(r?.review_status||'').toUpperCase()==='ACTIONABLE'||suggestedPrice(r)!==null}
function matchPriceFilter(r){const up=upcOf(r),p=prefix(up),t=priceType(r),urgent=trueUrgentPrice(r);if(pf==='urgent')return urgent;if(pf==='reg'||pf==='tpr'||pf==='clearance'||pf==='sale')return t===pf;if(pf==='240249')return p==='240'||p==='249';if(pf==='245')return p==='245';return true}
function renderPrice(){const rows=priceRows.filter(r=>actionablePrice(r)&&matchPriceFilter(r)&&!isIgnored('price:'+upcOf(r)));const familySet=new Set(rows.map(famOf).filter(Boolean));$('#priceActions').textContent=rows.length;$('#priceUrgent').textContent=rows.filter(trueUrgentPrice).length;$('#priceFamilies').textContent=familySet.size;$$('[data-pf]').forEach(b=>b.classList.toggle('active',b.dataset.pf===pf));const direct=!['all','urgent'].includes(pf);if(!direct){const groups={};rows.forEach(r=>{const f=famOf(r)||nameOf(r);(groups[f]||(groups[f]=[])).push(r)});$('#priceQueue').innerHTML=Object.entries(groups).map(([f,rs])=>{const u=rs.some(trueUrgentPrice);return`<div class="family-card ${u?'urgent':''}"><div class="family-head"><div class="family-accent"></div><div class="family-main"><div class="family-title">${esc(nameOf(rs[0]))}</div><div class="family-sub">Family ${esc(f)} · ${rs.length} UPC action${rs.length===1?'':'s'}</div><div style="margin-top:9px"><span class="pill ${u?'danger':'blue'}">${u?'URGENT':'ACTION'}</span></div></div><div class="family-side"><b>${rs.length}</b><span>ACTIONS</span></div></div></div>`}).join('')||'<div class="empty">No price actions in this filter.</div>'}else{$('#priceQueue').innerHTML=rows.filter(r=>prefix(upcOf(r))!=='249').map(r=>{const up=upcOf(r),sp=suggestedPrice(r),cp=currentPrice(r),t=priceType(r),u=trueUrgentPrice(r),key='price:'+up;return`<div class="direct-card"><div class="row space"><div><div class="result-name">${esc(nameOf(r))}</div><div class="action-meta">UPC ${esc(up)} · Family ${esc(famOf(r)||'—')}</div></div><span class="pill ${u?'danger':'blue'}">${esc(t.toUpperCase())}</span></div><div class="actionbox ${u?'danger':''}"><div class="action-label">PRIMARY ACTION</div><div class="action-value">${sp!==null?money(sp):'REVIEW'} · ${esc(t.toUpperCase())}</div><div class="why"><b>Why:</b> ${esc(priceReason(r))}</div></div><div class="summary3"><div class="stat"><b>CURRENT</b><span>${money(cp)}</span></div><div class="stat"><b>COST</b><span>${money(r?.current_cost??r?.cost)}</span></div><div class="stat"><b>EFF OH</b><span>${fmt(r?.current_oh??r?.effective_oh)} ${esc(r?.current_oh_uom||r?.effective_oh_uom||'')}</span></div></div><button class="ignore" data-pi="${esc(key)}">Ignore 12h</button></div>`}).join('')||'<div class="empty">No price actions in this filter.</div>';$$('[data-pi]').forEach(b=>b.onclick=()=>{setIgnore(b.dataset.pi);renderPrice()})}}
$$('[data-pf]').forEach(b=>b.onclick=()=>{pf=b.dataset.pf;renderPrice()});$('#priceSearchBtn').onclick=()=>{$('#priceSearchWrap').style.display=$('#priceSearchWrap').style.display==='none'?'block':'none'};$('#priceSearch').addEventListener('input',()=>{const q=$('#priceSearch').value.trim().toLowerCase();if(!q){renderPrice();return}const saved=priceRows;const filtered=saved.filter(r=>(nameOf(r)+' '+famOf(r)+' '+upcOf(r)+' '+artOf(r)).toLowerCase().includes(q));const old=priceRows;priceRows=filtered;renderPrice();priceRows=old});
loadUrgent();
})();
</script>
</body></html>'''.replace('__VERSION__', v)
